 2	    requires n > 0;
 3		requires k > n;
 4		ensures k_out >= 0;
 5	{
 6		k_out := k;
 7	    var j: int := 0;
 8	    while(j < n)
 9	        invariant 0 <= j <= n;
10	    {
11	        j := j + 1;
12	        k_out := k_out - 1;
13	    }
14	}

