     1	method main(n: int, k: int) returns (k_out: int)
     2	    requires n > 0;
     3		requires k > n;
     4		ensures k_out >= 0;
     5	{
     6		k_out := k;
     7	    var j: int := 0;
     8	    while(j < n)
     9	        invariant 0 <= j <= n;
    10	        invariant k_out == k - j;
    11	    {
    12	        j := j + 1;
    13	        k_out := k_out - 1;
    14	    }
    15	}
{"spec_element": "invariant",
 "proof_obligation": "bridge",
 "diagnosis": "The loop invariant only bounds j (0 <= j <= n) and says nothing about k_out. After the loop Dafny knows only the invariant and j >= n, so k_out is unconstrained and the postcondition k_out >= 0 cannot be derived. The invariant is too weak to bridge to the postcondition; adding k_out == k - j gives k_out == k - n > 0 at exit because k > n."}

